create table own_warehouse_transports (is_deleted boolean not null, id bigint generated by default as identity, own_warehouse_id bigint not null, transport_id bigint not null, primary key (id), constraint uk_warehouse_transport unique (own_warehouse_id, transport_id));
create table own_warehouses (is_active boolean not null, is_deleted boolean not null, latitude numeric(9,6) not null, longitude numeric(9,6) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, address TEXT, name varchar(255) not null, primary key (id));
create table partner_warehouses (accepts_air boolean not null, accepts_land boolean not null, accepts_sea boolean not null, is_active boolean not null, is_deleted boolean not null, latitude numeric(9,6) not null, longitude numeric(9,6) not null, created_at timestamp(6) not null, id bigint generated by default as identity, partner_id bigint not null, updated_at timestamp(6) not null, address TEXT, name varchar(255) not null, primary key (id));
create table partners (is_active boolean not null, is_deleted boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, api_key varchar(100) not null unique, contact_email varchar(255), name varchar(255) not null, primary key (id));
create table product_characteristics (is_deleted boolean not null, id bigint generated by default as identity, product_id bigint not null, attribute_name varchar(100) not null, attribute_value varchar(500) not null, primary key (id), constraint uq_product_characteristic_name unique (product_id, attribute_name));
create table products (is_deleted boolean not null, volume_m3 numeric(10,6) not null, weight_kg numeric(10,4) not null, created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, sku varchar(50) not null unique, description TEXT, name varchar(255) not null, primary key (id));
create table stock_movements (is_deleted boolean not null, quantity_after integer not null, quantity_change integer not null, created_at timestamp(6) not null, id bigint generated by default as identity, stock_id bigint not null, movement_type varchar(20) not null check ((movement_type in ('REPLENISHMENT','SHIPMENT','ADJUSTMENT'))), reason TEXT, primary key (id));
create table stocks (is_deleted boolean not null, quantity integer not null, reserved_quantity integer not null, id bigint generated by default as identity, own_warehouse_id bigint not null, product_id bigint not null, updated_at timestamp(6) not null, version bigint not null, primary key (id), constraint uq_stocks_warehouse_product unique (own_warehouse_id, product_id));
create table transports (cost_per_km numeric(10,2) not null, is_deleted boolean not null, max_volume_m3 numeric(10,2) not null, max_weight_kg numeric(10,2) not null, speed_km_h numeric(8,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, transport_type varchar(20) not null check ((transport_type in ('AUTO','RAILWAY','AVIATION'))), name varchar(255) not null, primary key (id));
create index idx_own_warehouse_transports_transport_id on own_warehouse_transports (transport_id);
create index idx_warehouses_partner_id on partner_warehouses (partner_id);
create index idx_warehouses_is_active on partner_warehouses (is_active);
create index idx_partners_is_active on partners (is_active);
create index idx_product_characteristics_product_id on product_characteristics (product_id);
create index idx_products_name on products (name);
create index idx_stock_movements_stock_id on stock_movements (stock_id);
create index idx_stock_movements_created_at on stock_movements (created_at);
create index idx_stock_movements_type on stock_movements (movement_type);
create index idx_stocks_own_warehouse_id on stocks (own_warehouse_id);
create index idx_stocks_product_id on stocks (product_id);
create index idx_transports_transport_type on transports (transport_type);
alter table if exists own_warehouse_transports add constraint FK2sfcemfy2mx9ti8aka6rn4a6f foreign key (own_warehouse_id) references own_warehouses;
alter table if exists own_warehouse_transports add constraint FKkfav1c4bwpnapne44b4t6rxbl foreign key (transport_id) references transports;
alter table if exists partner_warehouses add constraint FKdtu11ahgvrkt31tvj5r7a5peg foreign key (partner_id) references partners;
alter table if exists product_characteristics add constraint FKlwuvy71q239qxmgor4u6ni4ej foreign key (product_id) references products on delete cascade;
alter table if exists stock_movements add constraint FKfhk0y5524hlyl8kend6ei4id8 foreign key (stock_id) references stocks;
alter table if exists stocks add constraint FKff7be959jyco0iukc1dcjj9qm foreign key (product_id) references products;
